"use client";

import * as React from "react";
import { PlusSignIcon } from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { CreditCardForm } from "@/components/ui/credit-card-form";
import { CreditCardValues, PaymentMethod } from "@/types/payment";
import { detectCardType } from "@/hooks/use-card-type";

interface AddPaymentDialogProps {
  onAdd: (method: PaymentMethod) => void;
  isFirstCard?: boolean;
}

const EMPTY_CARD: CreditCardValues = {
  cardholderName: "",
  cardNumber: "",
  expiryMonth: "",
  expiryYear: "",
  cvv: "",
};

export function AddPaymentDialog({ onAdd, isFirstCard = false }: AddPaymentDialogProps) {
  const [open, setOpen] = React.useState(false);
  const [card, setCard] = React.useState<CreditCardValues>(EMPTY_CARD);

  const isValid =
    card.cardholderName.trim() &&
    card.cardNumber.replace(/\s/g, "").length >= 15 &&
    card.expiryMonth &&
    parseInt(card.expiryMonth) <= 12 &&
    card.expiryYear &&
    card.cvv.length >= 3;

  const handleSave = () => {
    if (!isValid) return;
    const type = detectCardType(card.cardNumber);
    const cleaned = card.cardNumber.replace(/\s/g, "");
    const newMethod: PaymentMethod = {
      id: Date.now().toString(),
      type: (type === "unknown" || type === "discover" ? "visa" : type) as PaymentMethod["type"],
      last4: cleaned.slice(-4),
      expiryMonth: parseInt(card.expiryMonth),
      expiryYear: parseInt(`20${card.expiryYear}`),
      isDefault: isFirstCard,
    };
    onAdd(newMethod);
    setCard(EMPTY_CARD);
    setOpen(false);
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm" className="h-8 gap-2">
          <HugeiconsIcon icon={PlusSignIcon} size={16} strokeWidth={2} />
          Add method
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-lg border-border/50 bg-muted/20 backdrop-blur-xl">
        <DialogHeader>
          <DialogTitle>Add Payment Method</DialogTitle>
          <DialogDescription>
            Submit your card information to securely add a new payment method.
          </DialogDescription>
        </DialogHeader>
        <CreditCardForm value={card} onChange={setCard} />
        <DialogFooter>
          <Button variant="outline" onClick={() => setOpen(false)}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={!isValid}>
            Save Card
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
